model.en:
Reset state per test and close the pool in teardown:

import { test, beforeEach, after } from 'node:test';
import assert from 'node:assert/strict';
import request from 'supertest';
import { app } from '../src/app.js';
import { pool } from '../src/db.js';

beforeEach(async () => {
  // deterministic clean slate before each test
  await pool.query('TRUNCATE users RESTART IDENTITY CASCADE');
});

test('creates a user', async () => {
  const res = await request(app).post('/users').send({ email: 'a@x.com' });
  assert.equal(res.status, 201);
});

test('lists exactly one user', async () => {
  await pool.query("INSERT INTO users(email) VALUES('seed@x.com')");
  const res = await request(app).get('/users');
  assert.equal(res.body.length, 1); // now self-contained
});

after(async () => {
  await pool.end(); // close the pool so the runner exits
});

Why it's right: beforeEach TRUNCATE (or a per-test transaction + rollback) makes each test independent of order and leftover rows, killing the flake. Each test seeds exactly what it needs instead of relying on a previous test. after(pool.end()) closes the live handle so the event loop drains and the process exits instead of hanging. For real fidelity, point this at a per-suite Testcontainers Postgres, not SQLite.

model.ru:
Сбрасывай состояние на тест и закрывай пул в teardown:

import { test, beforeEach, after } from 'node:test';
import assert from 'node:assert/strict';
import request from 'supertest';
import { app } from '../src/app.js';
import { pool } from '../src/db.js';

beforeEach(async () => {
  // детерминированный чистый лист перед каждым тестом
  await pool.query('TRUNCATE users RESTART IDENTITY CASCADE');
});

test('создаёт пользователя', async () => {
  const res = await request(app).post('/users').send({ email: 'a@x.com' });
  assert.equal(res.status, 201);
});

test('возвращает ровно одного пользователя', async () => {
  await pool.query("INSERT INTO users(email) VALUES('seed@x.com')");
  const res = await request(app).get('/users');
  assert.equal(res.body.length, 1); // теперь самодостаточен
});

after(async () => {
  await pool.end(); // закрыть пул, чтобы раннер вышел
});

Почему верно: beforeEach TRUNCATE (или транзакция на тест + rollback) делает каждый тест независимым от порядка и оставшихся строк, убивая флейк. Каждый тест сеет ровно то, что ему нужно, вместо опоры на предыдущий тест. after(pool.end()) закрывает живой хендл, чтобы event loop слился и процесс вышел, а не завис. Ради реальной достоверности направь это на Postgres в Testcontainers на набор, а не на SQLite.
